gPx(){return"\u0625\u0636\u0627\u0641\u0629 \u0644\u0648\u0646 / \u0642\u064a\u0627\u0633"},
DN(a){var s=""+a
return A.b3(a,s+" \u0623\u0644\u0648\u0627\u0646/\u0642\u064a\u0627\u0633\u0627\u062a",this.a,s+" \u0644\u0648\u0646\u0627\u064b/\u0642\u064a\u0627\u0633\u0627\u064b","\u0644\u0648\u0646/\u0642\u064a\u0627\u0633 \u0648\u0627\u062d\u062f",s+" \u0644\u0648\u0646/\u0642\u064a\u0627\u0633","\u0644\u0648\u0646\u0627\u0646/\u0642\u064a\u0627\u0633\u0627\u0646",null)},
ga7Q(){return"\u0645\u0633\u062d \u0628\u0627\u0631\u0643\u0648\u062f \u0639\u0644\u0628\u0629 \u0645\u0627\u062f\u0629 \u064a\u0633\u062d\u0628 \u0639\u0644\u0628\u0629 \u0648\u0627\u062d\u062f\u0629 \u0645\u0646 \u0627\u0644\u0645\u062e\u0632\u0646 \u0628\u0627\u0633\u0645\u0643."},
ga7R(){return"\u0647\u0630\u0627 \u0627\u0644\u0628\u0627\u0631\u0643\u0648\u062f \u063a\u064a\u0631 \u0645\u0631\u062a\u0628\u0637 \u0628\u0623\u064a \u0645\u0627\u062f\u0629 \u0641\u064a \u0627\u0644\u0645\u062e\u0632\u0646 \u0628\u0639\u062f \u2014 \u0627\u0637\u0644\u0628 \u0645\u0646 \u0627\u0644\u0645\u0633\u0624\u0648\u0644 \u0631\u0628\u0637\u0647."},
ga7S(){return"\u062a\u0631\u0627\u062c\u0639"},
ga7T(){return"\u062a\u0645 \u0627\u0644\u062a\u0631\u0627\u062c\u0639 \u2014 \u0623\u064f\u0639\u064a\u062f\u062a \u0627\u0644\u0639\u0644\u0628\u0629 \u0625\u0644\u0649 \u0627\u0644\u0645\u062e\u0632\u0646."},
gPY(){return"\u0644\u0648\u0646 / \u0642\u064a\u0627\u0633 \u0645\u062e\u062a\u0644\u0641\u061f"},
