gaag(){return"\u062e\u0627\u0631\u062c\u064a (\u0644\u064a\u0633 \u0645\u0646 \u0633\u0643\u0646\u0631 \u0627\u0644\u0645\u062e\u062a\u0628\u0631)"},
gaah(){return"\u0627\u062e\u062a\u0631 \u0633\u0643\u0646\u0631 \u0627\u0644\u0645\u062e\u062a\u0628\u0631 (\u0623\u0648 \xab\u062e\u0627\u0631\u062c\u064a\xbb)."},
gOE(){return"\u0627\u0644\u062d\u0627\u0644\u0629 \u0627\u0644\u062c\u062f\u064a\u062f\u0629: \u0627\u0644\u0646\u0648\u0639 \u0648\u0627\u0644\u0644\u0648\u0646 \u0648\u0627\u0644\u0623\u0633\u0646\u0627\u0646 \u0625\u062c\u0628\u0627\u0631\u064a\u0629"},
gOF(){return"\u0644\u0627 \u0634\u064a\u0621 \u064a\u064f\u062e\u062a\u0627\u0631 \u062a\u0644\u0642\u0627\u0626\u064a\u0627\u064b: \u064a\u062c\u0628 \u0627\u0644\u0636\u063a\u0637 \u0639\u0644\u0649 \u0646\u0648\u0639 \u0627\u0644\u062d\u0627\u0644\u0629\u060c \u0648\u062a\u062d\u062f\u064a\u062f \u0627\u0644\u0623\u0633\u0646\u0627\u0646 (\u0623\u0648 \u0627\u0644\u0641\u0643\u0648\u0643)\u060c \u0648\u0627\u062e\u062a\u064a\u0627\u0631 \u0627\u0644\u0644\u0648\u0646 \u0623\u0648 \xab\u064a\u062d\u062f\u062f \u0644\u0627\u062d\u0642\u0627\u064b\xbb \u0625\u0630\u0627 \u0643\u0627\u0646 \u0627\u0644\u0646\u0648\u0639 \u064a\u0633\u062a\u062e\u062f\u0645 \u0627\u0644\u0623\u0644\u0648\u0627\u0646. \u0627\u0644\u0637\u0628\u064a\u0628 \u064a\u064f\u0645\u0644\u0623 \u062a\u0644\u0642\u0627\u0626\u064a\u0627\u064b \u0641\u0642\u0637 \u0625\u0630\u0627 \u0643\u0627\u0646 \u0641\u064a \u0627\u0644\u0639\u064a\u0627\u062f\u0629 \u0637\u0628\u064a\u0628 \u0648\u0627\u062d\u062f."},
gNR(){return"\u0627\u0644\u062d\u0627\u0644\u0629 \u0627\u0644\u062c\u062f\u064a\u062f\u0629: \u0625\u062e\u0641\u0627\u0621 \u0627\u0644\u062a\u0643\u0644\u0641\u0629 \u0648\u0633\u0639\u0631 \u0627\u0644\u062f\u0648\u0644\u0627\u0631"},
gNS(){return"\u0644\u0644\u0645\u062e\u062a\u0628\u0631\u0627\u062a \u0627\u0644\u062a\u064a \u0644\u0627 \u062a\u062a\u0627\u0628\u0639 \u062a\u0643\u0644\u0641\u0629 \u0643\u0644 \u062d\u0627\u0644\u0629 \u0648\u0644\u0627 \u062a\u0633\u0639\u0651\u0631 \u0628\u0627\u0644\u062f\u0648\u0644\u0627\u0631. \u0627\u0644\u062a\u0643\u0644\u0641\u0629 \u0645\u0646 \u0627\u0644\u0643\u062a\u0627\u0644\u0648\u062c \u0648\u0633\u0639\u0631 \u0627\u0644\u062f\u0648\u0644\u0627\u0631 \u0627\u0644\u062d\u0627\u0644\u064a \u064a\u064f\u062d\u0641\u0638\u0627\u0646 \u0643\u0627\u0644\u0645\u0639\u062a\u0627\u062f\u060c \u0641\u0644\u0627 \u062a\u062a\u0623\u062b\u0631 \u0627\u0644\u062a\u0642\u0627\u0631\u064a\u0631. \u062a\u0639\u062f\u064a\u0644 \u0627\u0644\u062d\u0627\u0644\u0629 \u064a\u0628\u0642\u0649 \u064a\u0639\u0631\u0636\u0647\u0645\u0627."},
gMV(){return"\u0645\u0633\u062d QR \u0645\u0646 \u0627\u0644\u0635\u0648\u0631"},
gMW(){return"\u062a\u064f\u0638\u0647\u0631 \u0646\u0627\u0641\u0630\u0629 \xab\u0645\u0633\u062d QR\xbb \u0641\u064a \u0627\u0644\u0644\u0648\u062d\u0629 \u0632\u0631 \xab\u0645\u0646 \u0627\u0644\u0635\u0648\u0631\xbb: \u0627\u062e\u062a\u0631 \u0635\u0648\u0631 \u0645\u0644\u0635\u0642\u0627\u062a \u0627\u0644\u062d\u0627\u0644\u0627\u062a \u0645\u0646 \u0627\u0644\u0645\u0639\u0631\u0636\u060c \u0631\u0627\u062c\u0639\u0647\u0627\u060c \u062b\u0645 \u0631\u0642\u0650\u0651\u0647\u0627 \u0628\u0636\u063a\u0637\u0629 \u0648\u0627\u062d\u062f\u0629. \u0627\u0644\u0635\u0648\u0631\u0629 \u0644\u0627 \u062a\u064f\u062b\u0628\u062a \u0623\u0646 \u0627\u0644\u0639\u0645\u0644 \u0643\u0627\u0646 \u0623\u0645\u0627\u0645 \u0627\u0644\u0641\u0646\u064a\u060c \u0644\u0630\u0644\u0643 \u064a\u0628\u0642\u0649 \u0627\u0644\u062e\u064a\u0627\u0631 \u0645\u0637\u0641\u0623\u064b \u0645\u0627 \u0644\u0645 \u062a\u0641\u0639\u0651\u0644\u0647."},
gIW(){return"\u0627\u062e\u062a\u0631 \u0646\u0648\u0639 \u0627\u0644\u062d\u0627\u0644\u0629."},
aaq(a){return"\u062d\u062f\u0651\u062f \u0627\u0644\u0623\u0633\u0646\u0627\u0646 \u0644\u0640 "+a+"."},
aao(a){return"\u0627\u062e\u062a\u0631 \u0627\u0644\u0644\u0648\u0646 \u0644\u0640 "+a+" (\u0623\u0648 \xab\u064a\u062d\u062f\u062f \u0644\u0627\u062d\u0642\u0627\u064b\xbb)."},
gNd(){return"\u062a\u0631\u0648\u064a\u0633\u0629 \u0641\u064a \u0627\u0644\u0645\u0646\u062a\u0635\u0641 \u0628\u0627\u0644\u0645\u0633\u062a\u0646\u062f\u0627\u062a"},
gNc(){return"\u0639\u0646\u062f \u0627\u0644\u062a\u0634\u063a\u064a\u0644: \u0627\u0633\u0645 \u0627\u0644\u0645\u062e\u062a\u0628\u0631 \u0648\u0639\u0646\u0648\u0627\u0646\u0647 \u0641\u064a \u0645\u0646\u062a\u0635\u0641 \u0623\u0639\u0644\u0649 \u0627\u0644\u0641\u0648\u0627\u062a\u064a\u0631 \u0648\u0642\u0648\u0627\u0626\u0645 \u0627\u0644\u062d\u0627\u0644\u0627\u062a \u0648\u0643\u0634\u0648\u0641 \u0627\u0644\u062d\u0633\u0627\u0628\u060c \u0648\u0639\u0646\u0648\u0627\u0646 \u0627\u0644\u0645\u0633\u062a\u0646\u062f \u0648\u062a\u0627\u0631\u064a\u062e\u0647 \u0641\u064a \u0627\u0644\u0645\u0646\u062a\u0635\u0641 \u062a\u062d\u062a\u0647\u0645\u0627."},
gO4(){return"\u0627\u0644\u0623\u0633\u0646\u0627\u0646 \u0641\u064a \u0645\u0644\u0635\u0642 \u0627\u0644\u062d\u0627\u0644\u0629 \u0643\u0645\u062e\u0637\u0637 \u0635\u0644\u064a\u0628\u064a"},
gO3(){return"\u0639\u0646\u062f \u0627\u0644\u062a\u0634\u063a\u064a\u0644: \u064a\u0639\u0631\u0636 \u0627\u0644\u0645\u0644\u0635\u0642 \u0627\u0644\u0623\u0633\u0646\u0627\u0646 \u0641\u064a \u0627\u0644\u0623\u0631\u0628\u0627\u0639 \u0627\u0644\u0623\u0631\u0628\u0639\u0629 \u062d\u0648\u0644 \u0639\u0644\u0627\u0645\u0629 \xab+\xbb (\u0627\u0644\u0639\u0644\u0648\u064a \u0627\u0644\u0623\u064a\u0645\u0646 | \u0627\u0644\u0639\u0644\u0648\u064a \u0627\u0644\u0623\u064a\u0633\u0631 \u0641\u0648\u0642 \u0627\u0644\u0633\u0641\u0644\u064a \u0627\u0644\u0623\u064a\u0645\u0646 | \u0627\u0644\u0633\u0641\u0644\u064a \u0627\u0644\u0623\u064a\u0633\u0631)\u060c \u0643\u0645\u0627 \u0641\u064a \u0648\u0631\u0642\u0629 \u0627\u0644\u0645\u062e\u062a\u0628\u0631. \u0639\u0646\u062f \u0627\u0644\u0625\u064a\u0642\u0627\u0641: \u0633\u0637\u0631 \u0648\u0627\u062d\u062f \u0628\u0623\u0631\u0642\u0627\u0645 \u0623\u0648 \u062d\u0631\u0648\u0641 \u0627\u0644\u0623\u0633\u0646\u0627\u0646."},
gOG(){return"\u0633\u0643\u0646\u0631 \u0627\u0644\u0645\u062e\u062a\u0628\u0631 \u0625\u062c\u0628\u0627\u0631\u064a \u0639\u0646\u062f \u0625\u062f\u062e\u0627\u0644 \u0627\u0644\u062d\u0627\u0644\u0629"},
gOH(){return"\u0644\u0627 \u062a\u064f\u0646\u0634\u0623 \u0627\u0644\u062d\u0627\u0644\u0629 \u062d\u062a\u0649 \u064a\u064f\u062e\u062a\u0627\u0631 \u0627\u0644\u0633\u0643\u0646\u0631\u060c \u0623\u0648 \xab\u062e\u0627\u0631\u062c\u064a\xbb \u0644\u0644\u062d\u0627\u0644\u0629 \u0627\u0644\u062a\u064a \u0644\u0645 \u064a\u0633\u0648\u0650\u0651 \u0633\u0643\u0627\u0646\u0647\u0627 \u0627\u0644\u0645\u062e\u062a\u0628\u0631."},
gOr(){return"\u0627\u0644\u0623\u0633\u0646\u0627\u0646 \u0628\u062d\u0631\u0648\u0641 \u0627\u0644\u0623\u0631\u0628\u0627\u0639 \u0641\u064a \u0627\u0644\u0637\u0628\u0627\u0639\u0629 (UL1)"},
