ga99(){return"\u062a\u06d5\u0646\u0647\u0627 \u062e\u06c6\u062a \u062a\u06ce\u0628\u06cc\u0646\u06cc\u06cc\u06d5\u06a9\u0627\u0646\u062a \u062f\u06d5\u0628\u06cc\u0646\u06cc\u062a."},
ga96(){return"\u0647\u06ce\u0634\u062a\u0627 \u0647\u06cc\u0686 \u062a\u06ce\u0628\u06cc\u0646\u06cc\u06cc\u06d5\u06a9 \u0646\u06cc\u06cc\u06d5. \u0647\u06d5\u0631 \u0634\u062a\u06ce\u06a9 \u062f\u06d5\u062a\u06d5\u0648\u06ce\u062a \u062f\u0648\u0627\u062a\u0631 \u0628\u06c6\u06cc \u0628\u06af\u06d5\u0695\u06ce\u06cc\u062a\u06d5\u0648\u06d5 \u0628\u06cc\u0646\u0648\u0648\u0633\u06d5."},
a95(a){var s=null
return A.b3(a,s,this.a,s,"1 \u06a9\u0627\u062a\u06cc \u0647\u0627\u062a\u0648\u0648\u06d5",""+a+" \u06a9\u0627\u062a\u06cc\u0627\u0646 \u0647\u0627\u062a\u0648\u0648\u06d5",s,s)},
