ga5Z(){return"\u0631\u06ce\u0698\u0627 \u0628\u0644\u0646\u062f\u062a\u0631 \u0628\u06c6 \u0647\u06d5\u0631 \u06cc\u06d5\u06a9\u06d5\u06cc\u06d5\u06a9\u06ce"},
ga5Y(){return"\u0626\u0627\u0631\u06d5\u0632\u0648\u0648\u0645\u06d5\u0646\u062f\u0627\u0646\u06d5. \u0626\u06d5\u0648 \u06cc\u06d5\u06a9\u06ce\u0646 \u0698 \u06a4\u06ce \u0698\u0645\u0627\u0631\u06ce \u062f\u06d5\u0631\u0628\u0627\u0632 \u062f\u0628\u0646 \u062f \u0647\u06d5\u06cc\u06a4\u06d5\u06a9\u06ce \u062f\u0627 (\u0644 \u062f\u0648\u06cc\u06a4 \u0631\u06ce\u0632\u0628\u06d5\u0646\u062f\u06cc\u0627 \u062a\u06c6\u0645\u0627\u0631\u06a9\u0631\u0646\u0627 \u06a9\u06d5\u06cc\u0633\u0627\u0646) \u0628 \u0631\u06ce\u0698\u0627 \u0628\u0644\u0646\u062f\u062a\u0631 \u062f\u0647\u06ce\u0646\u06d5 \u062f\u0627\u0646\u060c \u0628\u06c6 \u0646\u0645\u0648\u0648\u0646\u06d5 600 \u06cc\u06d5\u06a9\u06ce\u0646 \u0626\u06ce\u06a9\u06ce \u0628 \u0631\u06ce\u0698\u0627 \u0626\u0627\u0633\u0627\u06cc\u06cc\u060c \u067e\u0627\u0634\u0627\u0646 1,500 \u0628\u06c6 \u0647\u06d5\u0631 \u06cc\u06d5\u06a9\u06d5\u06cc\u06d5\u06a9\u06ce. \u0631\u06ce\u0698\u06ce\u0646 \u062a\u0627\u06cc\u0628\u06d5\u062a \u0628 \u0645\u0627\u062f\u062f\u06ce \u06a4\u06d5 \u06a9\u0627\u0631 \u0644 \u0633\u06d5\u0631 \u0646\u0627\u0647\u06ce\u062a\u06d5 \u06a9\u0631\u0646. \u06a4\u0627\u0644\u0627 \u0628\u0647\u06ce\u0644\u06d5 \u0628\u06c6 \u0686 \u0646\u06cc\u0646\u06d5."},
ga5q(){return"\u0631\u06c6\u0698\u0627 \u0645\u0648\u0648\u0686\u06d5\u06cc (\u0626\u0627\u0631\u06d5\u0632\u0648\u0648\u0645\u06d5\u0646\u062f\u0627\u0646\u06d5\u060c 1-28)"},
ga5p(){return"\u0646\u06cc\u0633\u0628\u06d5 \u06a9\u06d5\u06cc\u0633\u06ce\u0646 \u06a4\u06cc \u06a9\u0627\u0631\u0645\u06d5\u0646\u062f\u06cc \u0698 \u0631\u06c6\u0698\u0627 \u067e\u0634\u062a\u06cc \u06a4\u06ce \u0631\u06c6\u0698\u06ce \u0647\u06d5\u062a\u0627 \u0647\u06d5\u0645\u0627\u0646 \u0631\u06c6\u0698 \u062f \u0647\u06d5\u06cc\u06a4\u0627 \u062f\u0627\u0647\u0627\u062a\u06cc \u062f\u0627 \u062f\u0647\u0698\u0645\u06ce\u0631\u06cc\u062a (\u0628\u06c6 \u0646\u0645\u0648\u0648\u0646\u06d5 4 = \u0698 5\u06ce \u0647\u06d5\u062a\u0627 4\u06ce). \u06a4\u0627\u0644\u0627 \u0628\u0647\u06ce\u0644\u06d5 \u0628\u06c6 \u0647\u06d5\u06cc\u06a4\u0627 \u0633\u0627\u0644\u0646\u0627\u0645\u06d5\u06cc\u06cc."},
