Xr(a){return"\u062f\u0627\u06af\u0631\u062a\u0646\u0627 \u0641\u0627\u06cc\u0644\u0627\u0646 \u0633\u06d5\u0631\u0646\u06d5\u06a9\u06d5\u0641\u062a: "+a},
